    /**
     * The service's own exceptions state a rule the caller broke and pass through unchanged;
     * anything else is wrapped as an unexpected failure of the operation.
     */
    private static SigningWorkflowServiceException failure(String operation, Throwable th)
    {
        if (th instanceof SigningWorkflowServiceException rule)
        {
            return rule;
        }
        return new SigningWorkflowServiceException("Error performing '" + operation + "' --> " + th, th);
    }
